mapper.update:
UPDATE normal_group_creation_item
SET current_step = 'CREATING_GROUP', dispatch_stage = 'CREATE',
    dispatch_status = 'PENDING', next_dispatch_at = #{now},
    processing_started_at = NULL,
    last_event_id = #{eventId}, last_error_code = NULL, last_error_message = NULL,
    updated_at = #{now}
WHERE id = #{itemId}
  AND current_step = 'PREPARING_CONTACTS'
  AND dispatch_status = 'PROCESSING'
  AND last_event_id = #{eventId}

UPDATE normal_group_creation_item_member
SET participant_status = #{status}, participant_raw_status = #{rawStatus}, updated_at = #{now}
WHERE id = #{memberId}

UPDATE normal_group_creation_item
SET group_jid = #{groupJid}, create_partial = #{createPartial},
    last_event_id = #{eventId}, updated_at = #{now}
WHERE id = #{itemId}
  AND current_step = 'CREATING_GROUP'
  AND dispatch_status = 'PROCESSING'
  AND last_event_id = #{eventId}
  AND group_jid IS NULL

UPDATE normal_group_creation_item
SET group_link_id = #{groupLinkId}, updated_at = #{now}
WHERE id = #{itemId}
  AND group_jid IS NOT NULL

UPDATE normal_group_creation_item
SET status = #{status}, dispatch_status = 'NONE', processing_started_at = NULL,
    last_event_id = #{eventId},
    last_error_code = #{errorCode}, last_error_message = #{errorMessage}, updated_at = #{now}
WHERE id = #{itemId}
  AND last_event_id = #{eventId}
  AND status NOT IN ('CREATED', 'CREATED_PARTIAL')

UPDATE normal_group_creation_item
SET dispatch_status = 'SENT', next_dispatch_at = #{now}, updated_at = #{now}
WHERE id = #{itemId}
  AND dispatch_stage = #{stage}
  AND dispatch_status = 'PENDING'
